    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="5" y="8" width="14" height="11" rx="2" /><path d="M8.5 8 5 4M15.5 8 19 4M9 19.5h6" />
